{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://json.schemas.assets.semio-tech.com/s/puzzle/puzzle2d/sqlite-laws.json",
  "title": "Puzzle 2D SQLite Snapshot Laws",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "snapshot",
    "binary64Words",
    "malformedSql",
    "control",
    "semanticCells"
  ],
  "properties": {
    "snapshot": {
      "$ref": "https://json.schemas.assets.semio-tech.com/s/puzzle/puzzle2d/snapshot.json"
    },
    "binary64Words": {
      "type": "array",
      "minItems": 9,
      "items": {
        "type": "string",
        "pattern": "^[0-9a-f]{16}$"
      }
    },
    "malformedSql": {
      "type": "array",
      "minItems": 18,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "control": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "collectionLength",
        "largeTextBytes",
        "maxOwnedBytes",
        "tinyFileBytes"
      ],
      "properties": {
        "collectionLength": {
          "const": 2048
        },
        "largeTextBytes": {
          "const": 131073
        },
        "maxOwnedBytes": {
          "const": 65536
        },
        "tinyFileBytes": {
          "const": 1024
        }
      }
    },
    "semanticCells": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "tableWidths",
        "fullRows"
      ],
      "properties": {
        "tableWidths": {
          "type": "array",
          "minItems": 20,
          "maxItems": 20,
          "items": {
            "type": "array",
            "minItems": 2,
            "maxItems": 2,
            "items": [
              {
                "type": "string",
                "pattern": "^puzzle2d_[a-z_]+$"
              },
              {
                "type": "integer",
                "minimum": 2,
                "maximum": 35
              }
            ],
            "additionalItems": false
          },
          "const": [
            [
              "puzzle2d_attribute",
              7
            ],
            [
              "puzzle2d_author",
              8
            ],
            [
              "puzzle2d_base_kind",
              4
            ],
            [
              "puzzle2d_camera",
              11
            ],
            [
              "puzzle2d_catalog_edge_kind",
              9
            ],
            [
              "puzzle2d_catalog_handle_kind",
              11
            ],
            [
              "puzzle2d_catalog_node_kind",
              11
            ],
            [
              "puzzle2d_catalog_wire_kind",
              10
            ],
            [
              "puzzle2d_compatible_kind",
              4
            ],
            [
              "puzzle2d_document",
              2
            ],
            [
              "puzzle2d_edge",
              35
            ],
            [
              "puzzle2d_handle",
              18
            ],
            [
              "puzzle2d_handle_template",
              19
            ],
            [
              "puzzle2d_kind_catalogs",
              2
            ],
            [
              "puzzle2d_kind_compatibility",
              8
            ],
            [
              "puzzle2d_meta",
              3
            ],
            [
              "puzzle2d_node",
              30
            ],
            [
              "puzzle2d_representation",
              9
            ],
            [
              "puzzle2d_representation_tag",
              4
            ],
            [
              "puzzle2d_target_region",
              19
            ]
          ]
        },
        "fullRows": {
          "const": 42
        }
      }
    }
  }
}

